begin;

-- departamentos.capital_codigo puede apuntar a un municipio que se inserta después.
set constraints all deferred;

on conflict (iso2) do update set
  iso3 = excluded.iso3,
  numerico = excluded.numerico,
  nombre = excluded.nombre,
  nombre_normalizado = excluded.nombre_normalizado,
  alias = excluded.alias,
  continente = excluded.continente,
  subregion = excluded.subregion,
  con_geometria = excluded.con_geometria,
  lon = excluded.lon,
  lat = excluded.lat;

on conflict (codigo) do update set
  nombre = excluded.nombre,
  nombre_corto = excluded.nombre_corto,
  nombre_normalizado = excluded.nombre_normalizado,
  alias = excluded.alias,
  iso_3166_2 = excluded.iso_3166_2,
  region = excluded.region,
  capital_codigo = excluded.capital_codigo,
  poblacion = excluded.poblacion,
  lon = excluded.lon,
  lat = excluded.lat,
  bbox = excluded.bbox;

on conflict (codigo) do update set
  departamento_codigo = excluded.departamento_codigo,
  nombre = excluded.nombre,
  nombre_normalizado = excluded.nombre_normalizado,
  tipo = excluded.tipo,
  es_capital = excluded.es_capital,
  lon = excluded.lon,
  lat = excluded.lat,
  codigo_geometria = excluded.codigo_geometria,
  bbox = excluded.bbox;

commit;
